--
-- Name: asking_price(public.listings); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.asking_price(l public.listings) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case when l.price >= 300 then l.price end
$$;

--
-- Name: auth_admin_request(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_admin_request(p_method text, p_path text, p_body jsonb DEFAULT NULL::jsonb) RETURNS TABLE(status integer, body jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_url      text;
  v_key      text;
  v_response extensions.http_response;
begin
  select s.decrypted_secret into v_url
  from vault.decrypted_secrets s where s.name = 'service_url';
  select s.decrypted_secret into v_key
  from vault.decrypted_secrets s where s.name = 'service_role_key';
  if v_url is null or v_key is null then
    raise exception 'Accounts are not available until the next collection'
      using errcode = '55000';
  end if;

  perform extensions.http_set_curlopt('CURLOPT_TIMEOUT_MS', '15000');
  v_response := extensions.http((
    p_method,
    v_url || '/auth/v1' || p_path,
    array[extensions.http_header('apikey', v_key),
          extensions.http_header('Authorization', 'Bearer ' || v_key)],
    'application/json',
    p_body::text
  )::extensions.http_request);

  status := v_response.status;
  body := case when v_response.content ~ '^\s*[\[{]'
               then v_response.content::jsonb end;
  return next;
end;
$$;

--
-- Name: bike_value(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bike_value(p_motorcycle_id uuid, p_year integer, p_mileage integer DEFAULT NULL::integer) RETURNS TABLE(comparable_count integer, fair_price numeric, low_price numeric, high_price numeric)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  with comparables as (
    select c.year, c.mileage, c.price,
           p_year is not null and abs(p_year - c.year) <= 3 as near
    from public.listings c
    where c.motorcycle_id = p_motorcycle_id
      and c.status in ('active', 'price_changed')
      and c.duplicate_of is null
      and c.price >= 300
      and (p_year is null or c.year is not null)
      and (p_mileage is null or c.mileage is not null)
  ),
  chosen as (
    select c.*
    from comparables c
    where c.near
       or (select count(*) from comparables n where n.near) < 5
  ),
  adjusted as (
    select ch.price * public.age_mileage_factor(
             p_year - ch.year,
             p_mileage - ch.mileage,
             coalesce(d.per_year, 0.04),
             coalesce(d.per_1000km, 0.002)
           ) as price
    from chosen ch
    left join public.model_depreciation d on d.motorcycle_id = p_motorcycle_id
  )
  select
    count(*)::integer,
    round((percentile_cont(0.5)  within group (order by price))::numeric, 2),
    round((percentile_cont(0.25) within group (order by price))::numeric, 2),
    round((percentile_cont(0.75) within group (order by price))::numeric, 2)
  from adjusted;
$$;

--
-- Name: bike_value_model(text, text, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bike_value_model(p_brand text, p_model text, p_olx_search text DEFAULT NULL::text, p_standvirtual_search text DEFAULT NULL::text, p_engine_cc_min integer DEFAULT NULL::integer, p_engine_cc_max integer DEFAULT NULL::integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_brand text := normalize(btrim(p_brand), NFC);
  v_model text := normalize(btrim(p_model), NFC);
  v_slug text;
  v_id uuid;
  v_range int4range := public.engine_range_from_name(v_model);
begin
  perform public.require_account();

  if nullif(v_brand, '') is null or nullif(v_model, '') is null then
    raise exception 'Brand and model are required' using errcode = '22023';
  end if;
  if p_engine_cc_min not between 1 and 3000
     or p_engine_cc_max not between 1 and 3000
     or p_engine_cc_min > p_engine_cc_max then
    raise exception 'Engine size range %-% is invalid',
      p_engine_cc_min, p_engine_cc_max using errcode = '22023';
  end if;

  v_slug := btrim(regexp_replace(lower(v_brand || '-' || v_model),
                                 '[^a-z0-9]+', '-', 'g'), '-');

  select m.id into v_id
  from public.motorcycles m
  where (lower(m.brand) = lower(v_brand) and lower(m.model) = lower(v_model))
     or m.slug = v_slug
  order by m.is_active desc, m.created_at
  limit 1;
  if v_id is not null then
    return v_id;
  end if;

  if p_engine_cc_min is null and p_engine_cc_max is null then
    p_engine_cc_min := lower(v_range);
    p_engine_cc_max := upper(v_range) - 1;
  end if;

  insert into public.motorcycles
    (brand, model, slug, min_year, is_active, collected_since,
     olx_search, standvirtual_search, engine_cc_min, engine_cc_max)
  values
    (v_brand, v_model, v_slug, extract(year from now())::integer, false, null,
     nullif(btrim(p_olx_search), ''),
     nullif(btrim(p_standvirtual_search), ''),
     p_engine_cc_min, p_engine_cc_max)
  returning id into v_id;
  return v_id;
end;
$$;

--
-- Name: bike_value_ready(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bike_value_ready(p_motorcycle_id uuid, p_year integer) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.motorcycles m
    where m.id = p_motorcycle_id
      and m.is_active
      and m.min_year <= greatest(p_year - 3, 1990)
      and exists (select 1 from public.collector_runs r
                  where r.started_at >= m.collected_since
                    and r.status in ('ok', 'partial'))
  )
$$;

--
-- Name: bike_value_request_days(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bike_value_request_days() RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$ select 30 $$;

--
-- Name: caller_tracks(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.caller_tracks(p_motorcycle_id uuid, p_year integer) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select case
    when coalesce((auth.jwt() ->> 'is_anonymous')::boolean, true)
    then public.collected(p_motorcycle_id, p_year)
    else public.user_tracks(auth.uid(), p_motorcycle_id, p_year)
  end
$$;

--
-- Name: catalog_search_url(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.catalog_search_url(p_source text, p_brand text, p_model text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_prefix text;
  v_brand text := normalize(btrim(p_brand), NFC);
  v_model text := normalize(btrim(p_model), NFC);
  v_brand_key text := regexp_replace(lower(v_brand), '[^[:alnum:]]', '', 'g');
  v_model_key text := regexp_replace(lower(v_model), '[^[:alnum:]]', '', 'g');
  v_make_id text;
  v_model_id text;
  v_words text;
begin
  v_prefix := case p_source
    when 'olx' then 'https://www.olx.pt/carros-motos-e-barcos/motociclos-scooters/'
    when 'standvirtual' then 'https://www.standvirtual.com/motos/'
  end;
  if v_prefix is null then
    raise exception 'Unsupported source %', p_source using errcode = '22023';
  end if;
  if nullif(v_brand_key, '') is null or nullif(v_model_key, '') is null then
    raise exception 'Brand and model must contain letters or numbers'
      using errcode = '22023';
  end if;

  select s.make_id, s.model_id into v_make_id, v_model_id
  from public.site_models s
  where s.source = p_source
    and regexp_replace(lower(normalize(s.make_name, NFC)), '[^[:alnum:]]', '', 'g') = v_brand_key
    and regexp_replace(lower(normalize(s.model_name, NFC)), '[^[:alnum:]]', '', 'g') = v_model_key
    and s.make_id ~* '^[a-z0-9][a-z0-9_-]*$'
    and s.model_id ~* '^[a-z0-9][a-z0-9_-]*$'
  order by s.make_id, s.model_id
  limit 1;

  if v_model_id is not null then
    if p_source = 'olx' then
      return v_prefix || v_make_id || '/'
        || '?search%5Bfilter_enum_modelo%5D%5B0%5D=' || v_model_id;
    end if;
    return v_prefix || v_make_id || '/' || v_model_id;
  end if;

  select s.make_id into v_make_id
  from public.site_models s
  where s.source = p_source
    and regexp_replace(lower(normalize(s.make_name, NFC)), '[^[:alnum:]]', '', 'g') = v_brand_key
    and s.make_id ~* '^[a-z0-9][a-z0-9_-]*$'
  order by s.make_id
  limit 1;

  -- OLX matches any query word: do not repeat the brand when its filter
  -- already restricts the search, or every bike of that brand matches.
  v_words := btrim(regexp_replace(
    lower(case when v_make_id is null then v_brand || ' ' || v_model else v_model end),
    '[^[:alnum:]]+', '-', 'g'), '-');
  return v_prefix || coalesce(v_make_id || '/', '') || 'q-' || v_words
    || case when p_source = 'olx' then '/' else '' end;
end;
$_$;

--
-- Name: check_collection_runs(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_collection_runs(p_now timestamp with time zone DEFAULT now()) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  last_run timestamptz;
  warned   timestamptz;
  message  text;
begin
  select max(r.started_at) into last_run from public.collector_runs r;
  -- No run ever recorded: a new project, nothing has broken yet.
  if last_run is null then
    return null;
  end if;

  select w.warned_at into warned from public.collection_watchdog w;

  if last_run < p_now - interval '9 hours' then
    if warned is not null and warned > p_now - interval '24 hours' then
      return null;
    end if;
    message :=
      '⚠️ Nenhuma recolha de anúncios começou nas últimas '
      || floor(extract(epoch from p_now - last_run) / 3600)::int
      || ' h (a última foi a '
      || to_char(last_run at time zone 'Europe/Lisbon', 'DD/MM "às" HH24:MI')
      || '). O token do GitHub no Supabase pode ter expirado ou o '
      || 'agendamento parou: veja "Scheduled runs" em docs/hosting.md.';
  elsif warned is not null then
    message := '✅ As recolhas de anúncios voltaram a começar.';
  else
    return null;
  end if;

  if public.send_telegram(message) is null then
    return null;
  end if;

  update public.collection_watchdog
  set warned_at = case when message like '✅%' then null else p_now end
  where id;
  return message;
end;
$$;

--
-- Name: github_token_check; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.github_token_check (
    id boolean DEFAULT true NOT NULL,
    checked_at timestamp with time zone,
    state text,
    http_status integer,
    expires_at timestamp with time zone,
    warned_on date,
    CONSTRAINT github_token_check_id_check CHECK (id),
    CONSTRAINT github_token_check_state_check CHECK ((state = ANY (ARRAY['ok'::text, 'missing'::text, 'refused'::text])))
);

--
-- Name: check_github_token(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_github_token() RETURNS public.github_token_check
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_token    text;
  v_response extensions.http_response;
  v_header   extensions.http_header;
  v_expires  timestamptz;
  v_row      public.github_token_check;
  v_message  text;
begin
  select s.decrypted_secret into v_token
  from vault.decrypted_secrets s where s.name = 'github_dispatch_token';

  if v_token is null then
    update public.github_token_check
    set checked_at = now(), state = 'missing', http_status = null, expires_at = null
    where id
    returning * into v_row;
    return v_row;
  end if;

  perform extensions.http_set_curlopt('CURLOPT_TIMEOUT_MS', '10000');
  v_response := extensions.http((
    'GET',
    'https://api.github.com/repos/rafaelfaria1323/motorcycle-deal-tracker'
      || '/actions/workflows/collect.yml',
    array[extensions.http_header('Authorization', 'Bearer ' || v_token),
          extensions.http_header('Accept', 'application/vnd.github+json'),
          extensions.http_header('X-GitHub-Api-Version', '2022-11-28'),
          extensions.http_header('User-Agent', 'motorcycle-deal-tracker')],
    null,
    null
  )::extensions.http_request);

  foreach v_header in array coalesce(v_response.headers, '{}') loop
    if lower(v_header.field) = 'github-authentication-token-expiration' then
      begin
        v_expires := v_header.value::timestamptz;
      exception when others then
        v_expires := null;
      end;
    end if;
  end loop;

  update public.github_token_check
  set checked_at = now(),
      state = case when v_response.status = 200 then 'ok' else 'refused' end,
      http_status = v_response.status,
      expires_at = v_expires
  where id
  returning * into v_row;

  if v_row.warned_on is distinct from current_date then
    if v_row.state = 'refused' then
      v_message := format(
        '🔑 O GitHub recusou o token que inicia as recolhas (HTTP %s). Sem ele '
        'as recolhas não começam: crie um novo e substitua-o no Vault do '
        'Supabase (docs/hosting.md).', v_row.http_status);
    elsif v_expires < now() + interval '14 days' then
      v_message := format(
        '🔑 O token do GitHub que inicia as recolhas expira a %s. Crie um novo '
        'e substitua-o no Vault do Supabase (docs/hosting.md).',
        to_char(v_expires at time zone 'Europe/Lisbon', 'DD/MM/YYYY'));
    end if;
    if v_message is not null and public.send_telegram(v_message) is not null then
      update public.github_token_check set warned_on = current_date where id
      returning * into v_row;
    end if;
  end if;
  return v_row;
end;
$$;

--
-- Name: collected(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.collected(p_motorcycle_id uuid, p_year integer) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
