--
-- Name: colour_code(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.colour_code(p_text text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select c.code
  from regexp_split_to_table(
         translate(lower(coalesce(p_text, '')),
                   'áàâãäéèêëíìîïóòôõöúùûüç', 'aaaaaeeeeiiiiooooouuuuc'),
         '[^a-z]+') with ordinality as w(word, n)
  join (values
    ('preto', 'black'), ('preta', 'black'), ('pretos', 'black'),
    ('pretas', 'black'), ('negro', 'black'), ('negra', 'black'),
    ('black', 'black'), ('nero', 'black'),
    ('branco', 'white'), ('branca', 'white'), ('brancos', 'white'),
    ('brancas', 'white'), ('white', 'white'), ('bianco', 'white'),
    ('cinzento', 'grey'), ('cinzenta', 'grey'), ('cinza', 'grey'),
    ('grafite', 'grey'), ('antracite', 'grey'), ('grey', 'grey'),
    ('gray', 'grey'),
    ('prateado', 'silver'), ('prateada', 'silver'), ('prata', 'silver'),
    ('silver', 'silver'),
    ('azul', 'blue'), ('azuis', 'blue'), ('blue', 'blue'),
    ('vermelho', 'red'), ('vermelha', 'red'), ('vermelhos', 'red'),
    ('vermelhas', 'red'), ('encarnado', 'red'), ('encarnada', 'red'),
    ('red', 'red'), ('rosso', 'red'),
    ('verde', 'green'), ('verdes', 'green'), ('green', 'green'),
    ('amarelo', 'yellow'), ('amarela', 'yellow'), ('yellow', 'yellow'),
    ('laranja', 'orange'), ('orange', 'orange'),
    ('castanho', 'brown'), ('castanha', 'brown'), ('brown', 'brown'),
    ('bege', 'beige'), ('beige', 'beige'),
    ('dourado', 'gold'), ('dourada', 'gold'), ('gold', 'gold'),
    ('roxo', 'purple'), ('roxa', 'purple'), ('violeta', 'purple'),
    ('lilas', 'purple'), ('purple', 'purple'), ('violet', 'purple'),
    ('rosa', 'pink'), ('pink', 'pink')
  ) as c(word, code) on c.word = w.word
  order by w.n
  limit 1
$$;

--
-- Name: colour_in_text(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.colour_in_text(p_variant text, p_description text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select coalesce(
    public.colour_code(split_part(lower(coalesce(p_variant, '')), ' com ', 1)),
    (select public.colour_code(m[1])
     from regexp_matches(lower(coalesce(p_description, '')),
            '\m(?:cor|colou?r)\M\s*[:=-]?\s*(?:(?:é|e|de|da|do)\s+)?([[:alpha:]]+)',
            'g') with ordinality as x(m, n)
     where public.colour_code(m[1]) is not null
     order by n
     limit 1))
$$;

--
-- Name: combine_deal_score(integer, integer, integer, integer, integer, integer, numeric, numeric, numeric, numeric, numeric, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.combine_deal_score(p_price_score integer, p_mileage_score integer, p_year_score integer, p_risk_score integer, p_extras integer DEFAULT 0, p_seller_score integer DEFAULT NULL::integer, p_w_price numeric DEFAULT 35, p_w_year_mileage numeric DEFAULT 20, p_w_risk numeric DEFAULT 10, p_w_seller numeric DEFAULT 10, p_mileage_share numeric DEFAULT 0.7, p_points_per_extra integer DEFAULT 1, p_max_extras integer DEFAULT 3, p_without_price integer DEFAULT 70) RETURNS TABLE(deal_score smallint, breakdown jsonb)
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  with slices(name, weight, score) as (
    values
      ('price', p_w_price, p_price_score::numeric),
      ('year_mileage', p_w_year_mileage,
        case
          when p_mileage_score is not null and p_year_score is not null
            then p_mileage_share * p_mileage_score
               + (1 - p_mileage_share) * p_year_score
          else coalesce(p_mileage_score, p_year_score)::numeric
        end),
      ('risk', p_w_risk,
        case when p_risk_score is null then null else 100 - p_risk_score end::numeric),
      ('seller', p_w_seller, p_seller_score::numeric)
  ),
  used as (select * from slices where score is not null),
  base as (
    select
      count(*) as n,
      case when count(*) > 0 then sum(weight * score) / sum(weight) end as score,
      bool_or(name = 'price') as has_price,
      coalesce(jsonb_object_agg(name, round(score, 1)), '{}'::jsonb) as scores,
      coalesce(jsonb_object_agg(name, weight), '{}'::jsonb) as weights
    from used
  ),
  bonus as (
    select p_points_per_extra * least(greatest(coalesce(p_extras, 0), 0), p_max_extras)
             as points
  )
  select
    case when b.n = 0 then null
         else round(least(
                case when b.has_price then 100 else p_without_price end,
                b.score + x.points))::smallint
    end,
    jsonb_build_object(
      'slices_used',     b.n,
      'slices_total',    4,
      'scores',          b.scores,
      'weights',         b.weights,
      'equipment_bonus', x.points,
      'capped_without_price',
        b.n > 0 and not coalesce(b.has_price, false)
        and b.score + x.points > p_without_price
    )
  from base b, bonus x
$$;

--
-- Name: cosmetic_damage(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cosmetic_damage(p_description text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select regexp_replace(
           regexp_replace(
             lower(coalesce(p_description, '')),
             '(\msem\M|\mnunca\M|\mn[ãa]o\M|\mnem\M|\mnenhu\w*|\mnada\M|livre\s+de|\mzero\M'
             '|isent[ao]\s+de)\s+([^\s.,!?;]+\s+){0,3}?(risc\w*|arranh\w*|mossas?|esfolad\w*)',
             ' ', 'g'),
           -- Insurance: "seguro contra todos os riscos".
           '(todos\s+os|contra|seguro\s+.{0,40})\s*riscos', ' ', 'g'
         ) ~ '(\mriscos?\M|riscad|arranh|\mmossas?\M|esfolad)'
$$;

--
-- Name: create_invite(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_invite(p_note text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_code text;
begin
  perform public.require_admin();
  insert into public.invites (note, created_by)
  values (nullif(btrim(p_note), ''), auth.uid())
  returning code into v_code;
  return v_code;
end;
$$;

--
-- Name: damage_allowance(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.damage_allowance(p_reasons text[]) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when p_reasons @> array['possible_accident', 'needs_repair'] then 0.20
    when 'possible_accident' = any(p_reasons) then 0.15
    when 'needs_repair' = any(p_reasons) then 0.10
    else 0
  end
$$;

--
-- Name: damage_cap(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.damage_cap(p_reasons text[]) RETURNS smallint
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case when p_reasons && array['possible_accident', 'needs_repair']
              then 79::smallint end
$$;

--
-- Name: database_usage(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.database_usage() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform public.require_admin();
  return jsonb_build_object(
    'database_bytes', pg_catalog.pg_database_size(pg_catalog.current_database()),
    'tables', coalesce((
      select jsonb_agg(jsonb_build_object('name', t.name, 'bytes', t.bytes)
                       order by t.bytes desc, t.name)
      from (
        select c.relname::text as name, pg_catalog.pg_total_relation_size(c.oid) as bytes
        from pg_catalog.pg_class c
        where c.relnamespace = 'public'::regnamespace and c.relkind in ('r', 'p', 'm')
        order by 2 desc, 1
        limit 5
      ) t
    ), '[]'::jsonb)
  );
end;
$$;

--
-- Name: dealer_score(bigint, bigint, bigint, bigint, bigint, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dealer_score(p_bikes bigint, p_relisted bigint, p_sharp_changes bigint, p_missing_mileage bigint, p_repeated bigint, p_min_bikes integer DEFAULT 5) RETURNS smallint
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when coalesce(p_bikes, 0) >= p_min_bikes then
      greatest(0, least(100, round(100 - 100.0 * (
        coalesce(p_relisted, 0)
        + coalesce(p_sharp_changes, 0)
        + coalesce(p_repeated, 0)
        + 0.5 * coalesce(p_missing_mileage, 0)
      ) / p_bikes)))::smallint
  end
$$;

--
-- Name: description_signals(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.description_signals(p_variant text, p_description text) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select array_remove(array[
    case when public.mentions_accident(p_description) then 'possible_accident' end,
    case when public.needs_repair(p_description) then 'needs_repair' end,
    case when public.cosmetic_damage(p_description) then 'cosmetic_damage' end,
    public.power_version(p_variant, p_description),
    case when public.single_owner_in_text(p_variant, p_description)
      then 'single_owner_in_text' end
  ], null)
$$;

--
-- Name: dismiss_alert(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dismiss_alert(p_alert uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform public.require_account();

  update public.alerts a
  set dismissed_at = coalesce(a.dismissed_at, now()),
      read_at = coalesce(a.read_at, now()),
      notified_at = coalesce(a.notified_at, now())
  where a.id = p_alert and a.user_id = (select auth.uid());

  if not found then
    raise exception 'Alert not found' using errcode = 'P0002';
  end if;
end;
$$;

--
-- Name: dismiss_read_alerts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dismiss_read_alerts() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_count integer;
begin
  perform public.require_account();

  update public.alerts a
  set dismissed_at = now(),
      notified_at = coalesce(a.notified_at, now())
  where a.user_id = (select auth.uid())
    and a.read_at is not null
    and a.dismissed_at is null;
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

