CREATE FUNCTION public.dispatch_collection(p_now timestamp with time zone DEFAULT now()) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not public.collection_due(p_now) then
    return null;
  end if;
  return public.dispatch_workflow('collect.yml');
end;
