--
-- Name: dispatch_workflow(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dispatch_workflow(p_workflow text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  token text;
begin
  if p_workflow not in ('collect.yml', 'weekly-summary.yml', 'photos.yml') then
    raise exception 'unknown workflow %', p_workflow;
  end if;

  select s.decrypted_secret into token
  from vault.decrypted_secrets s
  where s.name = 'github_dispatch_token';

  if token is null then
    raise warning 'github_dispatch_token is not in the Vault; % not started',
      p_workflow;
    return null;
  end if;

  return net.http_post(
    url := 'https://api.github.com/repos/rafaelfaria1323/motorcycle-deal-tracker'
           || '/actions/workflows/' || p_workflow || '/dispatches',
    body := '{"ref": "main"}'::jsonb,
    headers := jsonb_build_object(
      'Authorization', 'Bearer ' || token,
      'Accept', 'application/vnd.github+json',
      'Content-Type', 'application/json',
      'X-GitHub-Api-Version', '2022-11-28',
      'User-Agent', 'motorcycle-deal-tracker'
    ),
    timeout_milliseconds := 10000
  );
end;
$$;

--
-- Name: distance_between(double precision, double precision, double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.distance_between(p_lat1 double precision, p_lon1 double precision, p_lat2 double precision, p_lon2 double precision) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select round(2 * 6371 * asin(sqrt(
    power(sin(radians(p_lat2 - p_lat1) / 2), 2)
    + cos(radians(p_lat1)) * cos(radians(p_lat2))
      * power(sin(radians(p_lon2 - p_lon1) / 2), 2))))::integer
$$;

--
-- Name: distance_from_home(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.distance_from_home(p_user_id uuid, p_location text) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select public.distance_between(hp.lat, hp.lon, p.lat, p.lon)
  from public.user_home h
  join public.places hp on hp.key = h.place_key
  join public.places p on p.key = public.place_key(p_location)
  where h.user_id = p_user_id
$$;

