-- Name: distance_km(public.listings); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.distance_km(l public.listings) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
