--
-- Name: generate_alerts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_alerts() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  return public.generate_new_listing_alerts()
       + public.generate_price_reduction_alerts()
       + public.generate_excellent_opportunity_alerts()
       + public.generate_listing_removed_alerts()
       + public.generate_favourite_alerts()
       + public.generate_back_on_market_alerts()
       + public.generate_target_price_alerts();
end;
$$;

--
-- Name: generate_back_on_market_alerts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_back_on_market_alerts() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  n integer;
begin
  insert into public.alerts (
    user_id, saved_search_id, listing_id, type, old_price, new_price
  )
  select distinct on (w.user_id, l.id)
         w.user_id, w.saved_search_id, l.id,
         'back_on_market'::public.alert_type, l.relisted_price, l.price
  from public.listings l
  join (
    select f.user_id, f.listing_id, null::uuid as saved_search_id, 0 as rank
    from public.listing_favourites f
    union all
    select a.user_id, a.listing_id, s.id, 1
    from public.alerts a
    join public.saved_searches s on s.id = a.saved_search_id
    where s.is_active
      and a.type <> 'back_on_market'
      and a.dismissed_at is null
  ) w on w.listing_id = l.relisted_from
  where l.status in ('active', 'price_changed')
    and l.duplicate_of is null
    and l.first_seen_at > now() - interval '14 days'
  order by w.user_id, l.id, w.rank
  on conflict do nothing;

  get diagnostics n = row_count;
  return n;
end;
$$;

--
-- Name: generate_excellent_opportunity_alerts(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_excellent_opportunity_alerts(p_threshold integer DEFAULT 80, p_max_risk integer DEFAULT 50) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  n integer;
begin
  -- Remember the moment a listing becomes excellent...
  update public.listings
  set excellent_since = now()
  where excellent_since is null
    and deal_score >= p_threshold;

  -- ...and forget it when it falls back, so a later climb counts as new.
  update public.listings
  set excellent_since = null
  where excellent_since is not null
    and (deal_score is null or deal_score < p_threshold);

  insert into public.alerts (user_id, saved_search_id, listing_id, type, new_price)
  select distinct on (s.user_id, l.id)
         s.user_id, s.id, l.id, 'excellent_opportunity'::public.alert_type,
         l.price
  from public.saved_search_matches m
  join public.saved_searches s on s.id = m.saved_search_id
  join public.listings l on l.id = m.listing_id
  where s.is_active
    and s.notify_excellent_deal
    and l.deal_score >= p_threshold
    and coalesce(l.risk_score, 0) < p_max_risk
    and l.excellent_since > s.created_at
  order by s.user_id, l.id, s.created_at
  on conflict do nothing;

  get diagnostics n = row_count;
  return n;
end;
$$;

--
-- Name: generate_favourite_alerts(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_favourite_alerts(p_min_drop_pct numeric DEFAULT 1) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  drops   integer;
  removed integer;
begin
  insert into public.alerts (
    user_id, listing_id, type, old_price, new_price, price_history_id
  )
  select f.user_id, c.listing_id, 'price_reduction'::public.alert_type,
         c.old_price, c.new_price, c.history_id
  from (
    select h.id as history_id,
           h.listing_id,
           h.observed_at,
           h.price as new_price,
           lag(h.price) over (
             partition by h.listing_id order by h.observed_at, h.id
           ) as old_price
    from public.listing_price_history h
  ) c
  join public.listing_favourites f on f.listing_id = c.listing_id
  where c.old_price is not null
    and c.new_price < c.old_price
    and (c.old_price - c.new_price) / c.old_price * 100 >= p_min_drop_pct
    and c.observed_at > f.created_at
  on conflict do nothing;
  get diagnostics drops = row_count;

  insert into public.alerts (user_id, listing_id, type, new_price)
  select f.user_id, l.id, 'listing_removed'::public.alert_type, l.price
  from public.listing_favourites f
  join public.listings l on l.id = f.listing_id
  where l.status = 'removed'
    and l.last_checked_at > f.created_at
    and l.last_checked_at > now() - interval '1 day'
    and not exists (select 1 from public.alerts r
                    where r.user_id = f.user_id
                      and r.listing_id = l.id
                      and r.type = 'listing_removed'
                      and r.created_at >= l.last_checked_at);
  get diagnostics removed = row_count;

  return drops + removed;
end;
$$;

--
-- Name: generate_listing_removed_alerts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_listing_removed_alerts() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  n integer;
begin
  insert into public.alerts (user_id, saved_search_id, listing_id, type, new_price)
  select distinct on (a.user_id, a.listing_id)
         a.user_id, s.id, a.listing_id, 'listing_removed'::public.alert_type,
         l.price
  from public.alerts a
  join public.saved_searches s on s.id = a.saved_search_id
  join public.listings l on l.id = a.listing_id
  where a.type <> 'listing_removed'
    and a.dismissed_at is null
    and s.is_active
    and s.notify_listing_removed
    and l.status = 'removed'
    and l.last_checked_at > now() - interval '1 day'
    and not exists (select 1 from public.alerts r
                    where r.user_id = a.user_id
                      and r.listing_id = a.listing_id
                      and r.type = 'listing_removed'
                      and r.created_at >= l.last_checked_at)
  order by a.user_id, a.listing_id, a.created_at;

  get diagnostics n = row_count;
  return n;
end;
$$;

--
-- Name: generate_new_listing_alerts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_new_listing_alerts() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  n integer;
begin
  insert into public.alerts (user_id, saved_search_id, listing_id, type, new_price)
  select distinct on (s.user_id, l.id)
         s.user_id, s.id, l.id, 'new_listing'::public.alert_type, l.price
  from public.saved_search_matches m
  join public.saved_searches s on s.id = m.saved_search_id
  join public.listings l on l.id = m.listing_id
  where s.is_active
    and s.notify_new_listing
    and l.first_seen_at > greatest(s.created_at, now() - interval '1 day')
  order by s.user_id, l.id, s.created_at
  on conflict do nothing;

  get diagnostics n = row_count;
  return n;
end;
$$;

--
-- Name: generate_price_reduction_alerts(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_price_reduction_alerts(p_min_drop_pct numeric DEFAULT 1) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  n integer;
begin
  insert into public.alerts (
    user_id, saved_search_id, listing_id, type,
    old_price, new_price, price_history_id
  )
  select distinct on (s.user_id, c.history_id)
         s.user_id, s.id, c.listing_id, 'price_reduction'::public.alert_type,
         c.old_price, c.new_price, c.history_id
  from (
    select h.id as history_id,
           h.listing_id,
           h.observed_at,
           h.price as new_price,
           lag(h.price) over (
             partition by h.listing_id order by h.observed_at, h.id
           ) as old_price
    from public.listing_price_history h
  ) c
  join public.saved_search_matches m on m.listing_id = c.listing_id
  join public.saved_searches s on s.id = m.saved_search_id
  where c.old_price is not null
    and c.new_price < c.old_price
    and (c.old_price - c.new_price) / c.old_price * 100 >= p_min_drop_pct
    and s.is_active
    and s.notify_price_reduction
    and c.observed_at > greatest(s.created_at, now() - interval '1 day')
  order by s.user_id, c.history_id, s.created_at
  on conflict do nothing;

  get diagnostics n = row_count;
  return n;
end;
$$;

--
-- Name: generate_target_price_alerts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_target_price_alerts() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  n integer;
begin
  insert into public.alerts (user_id, listing_id, type, old_price, new_price)
  select f.user_id, l.id, 'target_price_reached'::public.alert_type,
         f.target_price, l.price
  from public.listing_favourites f
  join public.listings l on l.id = f.listing_id
  where f.target_price is not null
    and l.status in ('active', 'price_changed')
    and l.price <= f.target_price
    and exists (
      select 1
      from public.listing_price_history h
      where h.listing_id = l.id
        and h.price <= f.target_price
        and h.observed_at > f.target_set_at
    )
  on conflict do nothing;

  get diagnostics n = row_count;
  return n;
end;
$$;

--
-- Name: github_token_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.github_token_status() RETURNS TABLE(state text, http_status integer, expires_at timestamp with time zone, checked_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_row public.github_token_check;
begin
  perform public.require_admin();
  v_row := public.check_github_token();
  return query select v_row.state, v_row.http_status, v_row.expires_at, v_row.checked_at;
end;
$$;

--
-- Name: in_my_models(public.listings); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.in_my_models(l public.listings) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select public.caller_tracks(l.motorcycle_id, l.year)
$$;

--
-- Name: in_quiet_hours(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.in_quiet_hours(p_start integer, p_end integer, p_hour integer) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when p_start < p_end then p_hour >= p_start and p_hour < p_end
    else p_hour >= p_start or p_hour < p_end
  end
$$;

--
-- Name: in_removal_scope(public.listings, text[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.in_removal_scope(l public.listings, p_search_keys text[], p_include_unkeyed boolean) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_search_keys is null
      or l.search_key = any (p_search_keys)
      or (p_include_unkeyed and l.search_key is null)
      or (p_include_unkeyed
          and l.search_key <> all (p_search_keys)
          and exists (select 1
                      from public.motorcycles m
                      where m.id = l.motorcycle_id
                        and m.is_active
                        and (l.year is null or l.year >= m.min_year)));
$$;

--
-- Name: invite_status(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invite_status(p_code text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(
    (select case
              when i.used_at is not null then 'used'
              when i.expires_at <= now() then 'expired'
              else 'ok'
            end
     from public.invites i where i.code = p_code),
    'unknown')
$$;

