--
-- Name: place_key(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.place_key(p_name text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select nullif(btrim(regexp_replace(
    regexp_replace(
      translate(
        split_part(regexp_replace(lower(p_name), '\(.*?\)', ' ', 'g'), ',', 1),
        'áàâãäéèêëíìîïóòôõöúùûüçñ',
        'aaaaaeeeeiiiiooooouuuucn'),
      '[-''.]', ' ', 'g'),
    '\s+', ' ', 'g')), '')
$$;

--
-- Name: power_version(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.power_version(p_variant text, p_description text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  with t as (
    select regexp_replace(
             regexp_replace(
               regexp_replace(
                 lower(concat_ws(' ', p_variant, p_description)),
                 -- Something that could be done, not what was done:
                 -- "pode ser limitada a 35 kW", "fácil de deslimitar",
                 -- "ideal para limitar", "kit A2 incluído".
                 '(pode(ndo)?\s+(ser|ficar|se)|possibilidade\s+de(\s+ser)?'
                 '|f[áa]cil(mente)?(\s+de)?|op[çc][ãa]o\s+de|preparad[ao]\s+para(\s+ser)?'
                 '|\mpara)\s+(\w+\s+){0,2}?(des)?(limit|bloque|restring)\w*'
                 '(\s+(a|para|em|aos?)\s+(35\s*kw|a2|\d+\s*(cv|hp)))?',
                 ' ', 'g'),
               '(des)?limit[áa]vel(\s+(a|para|em|aos?)\s+(35\s*kw|a2|\d+\s*(cv|hp)))?'
               '|kit\s+(de\s+)?(limita[çc][ãa]o|a2)\s+(inclu[íi]d[ao]|oferta|em\s+oferta|dispon[íi]vel|opcional)',
               ' ', 'g'),
             -- "não está limitada": said of a full-power bike.
             'n[ãa]o\s+(est[áa]\s+|[ée]\s+|vem\s+)?limitad[ao]',
             ' ', 'g') as d
  )
  select case
    when d ~ '(deslimit|desbloque|desrestring)\w*'
      or d ~ '(limita[çc][ãa]o|kit(\s+a2)?|restri[çc][ãa]o)\s+(foi\s+|j[áa]\s+)?(removid|retirad|tirad)'
      or d ~ '(estava|esteve|era|vinha)\s+(\w+\s+){0,2}?limitad'
      then 'a2_unlocked'
    when d ~ '(vers[ãa]o\s+full|full\s+power|pot[êe]ncia\s+(total|m[áa]xima|completa))'
      then null
    when d ~ 'limitad[ao]'
      or d ~ '\m35\s*kw'
      or d ~ 'vers[ãa]o\s+(a2|35)'
      or d ~ '\ma2\s+(limitad|kit|montad)'
      or d ~ 'kit\s+(de\s+)?(limita[çc][ãa]o|a2)\s+(montad|instalad|colocad)'
      then 'a2_limited'
  end
  from t
$$;

--
-- Name: price_score(numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.price_score(p_price numeric, p_market_price numeric, p_points_per_percent numeric DEFAULT 5) RETURNS smallint
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when p_price is null or p_market_price is null or p_market_price <= 0
      then null
    else greatest(0, least(100, round(
      50 + (p_market_price - p_price) / p_market_price * 100 * p_points_per_percent
    )))::smallint
  end
$$;

--
-- Name: prune_anonymous_users(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prune_anonymous_users(p_idle_days integer DEFAULT 30) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_deleted integer;
begin
  delete from auth.users u
  where u.is_anonymous
    and u.created_at < pg_catalog.now() - pg_catalog.make_interval(days => p_idle_days)
    and not exists (
      select 1 from auth.sessions s
      where s.user_id = u.id
        -- greatest ignores nulls: the latest of the dates there are.
        and greatest(s.created_at, s.updated_at, s.refreshed_at at time zone 'utc')
            >= pg_catalog.now() - pg_catalog.make_interval(days => p_idle_days));
  get diagnostics v_deleted = row_count;
  return v_deleted;
end;
$$;

--
-- Name: prune_unfollowed_listings(bigint, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prune_unfollowed_listings(p_limit_bytes bigint DEFAULT ((400 * 1024) * 1024), p_min_days integer DEFAULT 30) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_bytes bigint := pg_catalog.pg_database_size(pg_catalog.current_database());
  v_deleted integer;
begin
  if v_bytes < p_limit_bytes then
    return 0;
  end if;

  delete from public.listings l
  where l.status in ('removed', 'sold')
    and l.source in ('olx', 'standvirtual')
    and l.last_checked_at < now() - pg_catalog.make_interval(days => p_min_days)
    and not exists (select 1 from public.motorcycles m
                    where m.id = l.motorcycle_id and m.is_active)
    and not exists (select 1 from public.listing_favourites f where f.listing_id = l.id)
    and not exists (select 1 from public.alerts a where a.listing_id = l.id)
    and not exists (select 1 from public.listings o
                    where o.relisted_from = l.id or o.duplicate_of = l.id);
  get diagnostics v_deleted = row_count;

  if v_deleted > 0 then
    perform public.send_telegram(pg_catalog.format(
      '🧹 A base de dados chegou a %s MB (limite gratuito: 500 MB): foram apagados %s anúncios antigos de modelos que ninguém acompanha.',
      v_bytes / (1024 * 1024), v_deleted));
  end if;
  return v_deleted;
end;
$$;

--
-- Name: push_keys(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.push_keys() RETURNS TABLE(public_key text, private_key text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select c.public_key, s.decrypted_secret
  from public.push_config c
  join vault.decrypted_secrets s on s.name = 'vapid_private_key'
$$;

--
-- Name: recalculate_deal_scores(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalculate_deal_scores() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET jit TO 'off'
    AS $$
declare
  n integer;
begin
  with dealers as (
    select d.dealer_key, d.bikes,
           public.dealer_score(d.bikes, d.relisted, d.sharp_changes,
                               d.missing_mileage, d.repeated) as score
    from public.dealer_reliability d
  ),
  scored as materialized (
    select
      l.id,
      l.price,
      ps.market_price,
      public.damage_allowance(rs.reasons) as allowance,
      ps.pct_below_market,
      ps.listing_count,
      coalesce(public.mileage_use_score(l.mileage, l.year),
               -- Hidden mileage: no better than an average-to-high one.
               case when l.year is not null then 50 end) as m_score,
      public.age_score(l.year)        as y_score,
      rs.risk_score,
      rs.reasons,
      coalesce(l.text_extras,
               public.listing_extras(l.variant, l.description)) as extras,
      dl.score as seller_score,
      dl.bikes as dealer_bikes
    from public.listings l
    left join public.listing_price_scores ps on ps.listing_id = l.id
    left join public.listing_risk_scores  rs on rs.listing_id = l.id
    left join dealers dl
      on l.seller_type = 'dealer'
     and dl.dealer_key = lower(btrim(l.seller_name))
    where l.status in ('active', 'price_changed')
      and l.duplicate_of is null
      and l.motorcycle_id is not null
  ),
  combined as (
    select
      s.id,
      s.risk_score,
      s.allowance,
      case
        when c.deal_score > public.damage_cap(s.reasons)
          then public.damage_cap(s.reasons)
        else c.deal_score
      end as deal_score,
      c.breakdown || jsonb_build_object(
        'market_price',         s.market_price,
        'pct_below_market',     s.pct_below_market,
        'market_listing_count', s.listing_count,
        'risk_reasons',         to_jsonb(coalesce(s.reasons, '{}'::text[])),
        'extras',               to_jsonb(s.extras),
        'valued_extras',        to_jsonb(public.valued_extras(s.extras)),
        'dealer_bikes',         s.dealer_bikes,
        'damage_allowance',     nullif(s.allowance, 0),
        'damaged_value',
          case when s.allowance > 0 then round(s.damaged_value) end,
        'pct_below_damaged_value',
          case when s.allowance > 0 and s.damaged_value > 0
               then round((s.damaged_value - s.price) / s.damaged_value * 100, 1)
          end,
        'capped_for_damage',
          coalesce(c.deal_score > public.damage_cap(s.reasons), false)
      ) as breakdown
    from (
      -- The price is scored against the value of the bike with its damage,
      -- so a damaged bike well below that still ranks high.
      select s0.*,
             s0.market_price * (1 - s0.allowance) as damaged_value,
             case when s0.listing_count >= 3
                  then public.price_score(s0.price,
                         s0.market_price * (1 - s0.allowance), 2.5)
             end as price_score
      from scored s0
    ) s
    cross join lateral public.combine_deal_score(
      s.price_score, s.m_score, s.y_score, s.risk_score,
      cardinality(public.valued_extras(s.extras)), s.seller_score
    ) c
  )
  update public.listings l
  set deal_score      = c.deal_score,
      risk_score      = c.risk_score,
      score_breakdown = c.breakdown,
      scored_at       = now()
  from combined c
  where l.id = c.id;

  get diagnostics n = row_count;

  update public.listings
  set deal_score = null, risk_score = null,
      score_breakdown = null, scored_at = null
  where (status not in ('active', 'price_changed')
         or duplicate_of is not null
         or motorcycle_id is null)
    and (deal_score is not null or risk_score is not null
         or score_breakdown is not null);

  return n;
end;
$$;

--
-- Name: record_initial_price(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_initial_price() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.price is not null then
    insert into public.listing_price_history (listing_id, price, observed_at)
    values (new.id, new.price, coalesce(new.first_seen_at, now()));
  end if;
  return new;
end;
$$;

--
-- Name: redeem_invite(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.redeem_invite(p_code text, p_email text, p_password text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_email  text := lower(btrim(p_email));
  v_status integer;
  v_body   jsonb;
  v_user   uuid;
begin
  perform 1 from public.invites i
  where i.code = p_code and i.used_at is null and i.expires_at > now()
  for update;
  if not found then
    raise exception 'This invite cannot be used' using errcode = 'P0002';
  end if;
  if v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then
    raise exception 'Invalid email' using errcode = '22023';
  end if;
  if char_length(coalesce(p_password, '')) < 8 then
    raise exception 'The password needs at least 8 characters' using errcode = '22023';
  end if;

  select r.status, r.body into v_status, v_body
  from public.auth_admin_request('POST', '/admin/users', jsonb_build_object(
    'email', v_email, 'password', p_password, 'email_confirm', true)) r;

  if v_status = 422
     and coalesce(v_body ->> 'error_code', v_body ->> 'code') = 'email_exists' then
    raise exception 'This email already has an account' using errcode = '23505';
  elsif v_status = 422
     and coalesce(v_body ->> 'error_code', v_body ->> 'code') = 'weak_password' then
    raise exception 'The password is too weak' using errcode = '22023';
  elsif v_status not between 200 and 299 or v_body ->> 'id' is null then
    raise exception 'Supabase Auth answered % %', v_status,
      coalesce(v_body ->> 'msg', v_body ->> 'message', '')
      using errcode = '58000';
  end if;

  v_user := (v_body ->> 'id')::uuid;
  update public.invites
  set used_at = now(), used_by = v_user
  where code = p_code;
  return v_user;
end;
$_$;

--
-- Name: refresh_collected_model(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_collected_model(p_motorcycle_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_was boolean;
  v_now boolean;
  v_min integer;
  v_followed boolean;
  v_follow_min integer;
  v_request_min integer;
begin
  select m.is_active into v_was
  from public.motorcycles m where m.id = p_motorcycle_id
  for update;

  select count(*) > 0, min(u.min_year) into v_followed, v_follow_min
  from public.user_models u
  where u.motorcycle_id = p_motorcycle_id and u.tracked;

  -- min() is null without requests (greatest() would turn it into 1990).
  select min(greatest(r.year - 3, 1990)) into v_request_min
  from public.bike_value_requests r
  where r.motorcycle_id = p_motorcycle_id
    and r.requested_at > now()
        - pg_catalog.make_interval(days => public.bike_value_request_days());

  v_now := v_followed or v_request_min is not null;
  -- least() ignores nulls: whichever of the two is known.
  v_min := least(v_follow_min, v_request_min);

  update public.motorcycles
  set is_active = v_now,
      min_year = coalesce(v_min, min_year),
      collected_since = case
        when not v_now then null
        when v_was then collected_since
        else now()
      end,
      updated_at = now()
  where id = p_motorcycle_id;

  if v_now and not v_was then
    update public.listings l
    set motorcycle_id = m.id
    from public.motorcycles m
    where m.id = p_motorcycle_id
      and l.motorcycle_id is null
      and lower(l.brand) = lower(m.brand)
      and lower(l.model) = lower(m.model);
  elsif v_was and not v_now then
    update public.listings set motorcycle_id = null
    where motorcycle_id = p_motorcycle_id;
  end if;

  if v_now is distinct from v_was then
    perform public.recalculate_deal_scores();
  end if;
end;
$$;

--
-- Name: refresh_photo_hints(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_photo_hints(p_listings uuid[]) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  update public.listings l
  set photo_hints = public.photo_hint_codes(coalesce((
    select jsonb_agg(jsonb_build_object(
      'photo', f.photo,
      'scores', f.scores || coalesce(jsonb_build_object('learned', round(
        public.photo_learned_share(f.model, f.features)::numeric, 3)), '{}')))
    from public.listing_photo_features f
    where f.listing_id = l.id
  ), '[]'))
  where l.id = any (p_listings)
$$;

--
-- Name: rematch_listings(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rematch_listings(p_source text, p_matches jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  n integer;
begin
  update public.listings l
  set motorcycle_id = nullif(m.value ->> 'motorcycle_id', '')::uuid,
      brand         = m.value ->> 'brand',
      model         = m.value ->> 'model'
  from jsonb_each(p_matches) m
  where l.source = p_source
    and l.source_listing_id = m.key
    and l.motorcycle_id is distinct from
        nullif(m.value ->> 'motorcycle_id', '')::uuid;

  get diagnostics n = row_count;
  return n;
end;
$$;

--
-- Name: remove_account(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remove_account(p_user uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_status  integer;
  v_models  uuid[];
  v_model   uuid;
begin
  perform public.require_admin();
  if p_user = auth.uid() then
    raise exception 'You cannot remove your own account' using errcode = '22023';
  end if;
  if not exists (select 1 from auth.users u
                 where u.id = p_user and not coalesce(u.is_anonymous, false)) then
    raise exception 'Unknown account %', p_user using errcode = 'P0002';
  end if;

  select coalesce(array_agg(m.motorcycle_id), '{}') into v_models
  from public.user_models m where m.user_id = p_user and m.tracked;

  select r.status into v_status
  from public.auth_admin_request('DELETE', '/admin/users/' || p_user) r;
  if v_status not between 200 and 299 and v_status <> 404 then
    raise exception 'Supabase Auth answered %', v_status using errcode = '58000';
  end if;

  -- Auth deletes the user in its own transaction; drop what is ours now
  -- too, so the collection follows at once.
  delete from public.user_models where user_id = p_user;
  foreach v_model in array v_models loop
    perform public.refresh_collected_model(v_model);
  end loop;
end;
$$;

--
-- Name: request_bike_value(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_bike_value(p_motorcycle_id uuid, p_year integer, p_mileage integer DEFAULT NULL::integer) RETURNS TABLE(request_id uuid, ready boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_ready boolean;
  v_id uuid;
begin
  perform public.require_account();

  if not exists (select 1 from public.motorcycles m where m.id = p_motorcycle_id) then
    raise exception 'Unknown model %', p_motorcycle_id using errcode = 'P0002';
  end if;
  if p_year < 1990 or p_year > extract(year from now())::integer + 1 then
    raise exception 'Year % is out of range', p_year using errcode = '22023';
  end if;
  if p_mileage < 0 then
    raise exception 'Mileage % is invalid', p_mileage using errcode = '22023';
  end if;

  v_ready := public.bike_value_ready(p_motorcycle_id, p_year);

  if not v_ready then
    select r.id into v_id
    from public.bike_value_requests r
    where r.user_id = auth.uid()
      and r.motorcycle_id = p_motorcycle_id
      and r.year = p_year
      and r.mileage is not distinct from p_mileage
      and r.answered_at is null
    limit 1;
    if v_id is not null then
      return query select v_id, false;
      return;
    end if;

    if (select count(*) from public.bike_value_requests r
        where r.user_id = auth.uid() and r.waited
          and r.requested_at > now() - interval '1 day') >= 3 then
      raise exception 'At most 3 valuations that wait for a collection a day'
        using errcode = '54000';
    end if;
  end if;

  insert into public.bike_value_requests
    (motorcycle_id, year, mileage, waited, answered_at)
  values
    (p_motorcycle_id, p_year, p_mileage, not v_ready,
     case when v_ready then now() end)
  returning id into v_id;

  -- A ready request also keeps the model collected (its figures stay
  -- fresh for the next 30 days' requests).
  perform public.refresh_collected_model(p_motorcycle_id);

  return query select v_id, v_ready;
end;
$$;

--
-- Name: request_photo_exam(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_photo_exam(p_listing uuid) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_listing public.listings%rowtype;
begin
  perform public.require_account();

  select l.* into v_listing
  from public.listings l
  join public.motorcycles m on m.id = l.motorcycle_id and m.is_active
  where l.id = p_listing
    and l.status in ('active', 'price_changed');
  if not found then
    raise exception 'Listing % is not collected or not live', p_listing
      using errcode = 'P0002';
  end if;
  if v_listing.photos_examined_all_at is not null then
    return null;
  end if;
  if cardinality(v_listing.images) <= 3 then
    raise exception 'Listing % has no photos beyond the first 3', p_listing
      using errcode = '22023';
  end if;

  if v_listing.photo_exam_requested_at is not null then
    -- Already waiting: this account is told too when it is done.
    insert into public.photo_exam_requests (user_id, listing_id)
    values (auth.uid(), p_listing)
    on conflict (user_id, listing_id) do nothing;
    return v_listing.photo_exam_requested_at;
  end if;

  if (select count(*) from public.photo_exam_requests r
      where r.user_id = auth.uid()
        and r.requested_at > now() - interval '1 day') >= 5 then
    raise exception 'At most 5 photo examinations a day'
      using errcode = '54000';
  end if;

  insert into public.photo_exam_requests (user_id, listing_id)
  values (auth.uid(), p_listing)
  on conflict (user_id, listing_id) do update set requested_at = now();

  update public.listings
  set photo_exam_requested_at = now()
  where id = p_listing;

  perform public.dispatch_workflow('photos.yml');

  return now();
end;
$$;

--
-- Name: require_account(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.require_account() RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
begin
  if auth.uid() is null
     or coalesce((auth.jwt() ->> 'is_anonymous')::boolean, true) then
    raise exception 'Sign in to change the tracked models'
      using errcode = '42501';
  end if;
end;
$$;

