-- Name: require_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.require_admin() RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not public.is_admin() then
    raise exception 'Only an admin can do this' using errcode = '42501';
  end if;
end;
$$;

--
-- Name: risk_assessment(numeric, numeric, integer, integer, text, text, boolean, boolean, integer, boolean, text, date, integer, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.risk_assessment(p_price numeric, p_market_price numeric, p_year integer, p_mileage integer, p_description text, p_location text, p_details_known boolean DEFAULT false, p_private_seller boolean DEFAULT false, p_registrations integer DEFAULT NULL::integer, p_service_book boolean DEFAULT NULL::boolean, p_origin text DEFAULT NULL::text, p_warranty_until date DEFAULT NULL::date, p_relists integer DEFAULT 0, p_on_sale_since timestamp with time zone DEFAULT NULL::timestamp with time zone, p_variant text DEFAULT NULL::text) RETURNS TABLE(risk_score smallint, reasons text[])
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select * from public.risk_from_signals(
    p_price, p_market_price, p_year, p_mileage, p_description, p_location,
    p_details_known, p_private_seller, p_registrations, p_service_book,
    p_origin, p_warranty_until, p_relists, p_on_sale_since,
    public.description_signals(p_variant, p_description))
$$;

--
-- Name: risk_from_signals(numeric, numeric, integer, integer, text, text, boolean, boolean, integer, boolean, text, date, integer, timestamp with time zone, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.risk_from_signals(p_price numeric, p_market_price numeric, p_year integer, p_mileage integer, p_description text, p_location text, p_details_known boolean, p_private_seller boolean, p_registrations integer, p_service_book boolean, p_origin text, p_warranty_until date, p_relists integer, p_on_sale_since timestamp with time zone, p_text_signals text[]) RETURNS TABLE(risk_score smallint, reasons text[])
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  -- Measured against the value of the bike with its damage
  -- (damage_allowance): a damaged bike priced like one isn't suspicious.
  with pct as (
    select case
      when p_price is null or p_market_price is null or p_market_price <= 0
        then null
      else (m.value - p_price) / m.value * 100
    end as below
    from (select p_market_price
                 * (1 - public.damage_allowance(p_text_signals)) as value) m
  ),
  signals(code, points) as (
    select 'price_far_below_market'::text, 45 from pct where below >= 25
    union all
    select 'price_below_market', 25 from pct where below >= 15 and below < 25
    union all
    select 'possible_accident', 30
    where 'possible_accident' = any(p_text_signals)
    union all
    select 'needs_repair', 20
    where 'needs_repair' = any(p_text_signals)
    union all
    select 'cosmetic_damage', 5
    where 'cosmetic_damage' = any(p_text_signals)
    union all
    select 'photos_reused', 10
    where 'photos_reused' = any(p_text_signals)
    union all
    select 'no_mileage', 15 where p_mileage is null
    union all
    select 'no_year', 10 where p_year is null
    union all
    -- A placeholder ("0", "1", "10") on a bike three or more years old, or
    -- far more than anyone rides in a year (bikes average 3-6 000 km). The
    -- age counts from mid-year registration in days, at least one year, as
    -- expected_mileage does.
    select 'suspicious_mileage', 10
    where p_mileage is not null and p_year is not null
      and (
        (p_mileage < 100
          and p_year <= extract(year from current_date)::integer - 3)
        or p_mileage::numeric
           / greatest(1, public.decimal_year() - (p_year + 0.5))
           > 25000
      )
    union all
    -- Only meaningful once the page was read, and only for private sellers:
    -- dealers rarely write more than boilerplate.
    select 'thin_description', 10
    where p_details_known and p_private_seller
      and char_length(btrim(coalesce(p_description, ''))) < 40
    union all
    select 'no_location', 5
    where nullif(btrim(coalesce(p_location, '')), '') is null
    union all
    select 'many_owners', 15 where p_registrations >= 3
    union all
    select 'no_service_book', 10 where p_service_book = false
    union all
    select 'imported', 10 where p_origin is not null and p_origin <> 'national'
    union all
    -- The text says something else than the ad's own fields.
    select c, 10 from unnest(public.text_contradictions(
      p_description, p_year, p_mileage, p_origin, p_service_book)) c
    union all
    -- A bike put up again after its ad went (mark_relists): it did not sell
    -- at that price. More when it happened twice or the bike has been on
    -- sale for over 90 days counting the earlier ads.
    select 'relisted_often', 10
    where p_relists >= 2
       or (p_relists = 1 and p_on_sale_since < now() - interval '90 days')
    union all
    select 'relisted', 5
    where p_relists = 1
      and (p_on_sale_since is null or p_on_sale_since >= now() - interval '90 days')
    union all
    -- An A2 (35 kW) version, still held back or unlocked (power_version).
    select v, case v when 'a2_limited' then 15 else 10 end
    from unnest(p_text_signals) v
    where v in ('a2_limited', 'a2_unlocked')
    union all
    -- The ad's field, or the text when the field is empty.
    select 'first_owner', -5
    where p_registrations = 1
       or (p_registrations is null
           and 'single_owner_in_text' = any(p_text_signals))
    union all
    select 'service_book', -5 where p_service_book
    union all
    select 'under_warranty', -10 where p_warranty_until >= current_date
  )
  select
    greatest(0, least(100, coalesce(sum(points), 0)))::smallint,
    coalesce(array_agg(code order by points desc, code), '{}'::text[])
  from signals
$$;

--
-- Name: save_push_subscription(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_push_subscription(p_endpoint text, p_p256dh text, p_auth text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  android boolean := p_endpoint ~ '^fcm:[A-Za-z0-9_:.-]{20,}$';
begin
  perform public.require_account();

  if not android
     and (p_endpoint not like 'https://%'
          or nullif(btrim(p_p256dh), '') is null
          or nullif(btrim(p_auth), '') is null) then
    raise exception 'Invalid push subscription' using errcode = '22023';
  end if;

  insert into public.push_subscriptions (endpoint, user_id, p256dh, auth)
  values (p_endpoint, auth.uid(),
          case when android then '' else btrim(p_p256dh) end,
          case when android then '' else btrim(p_auth) end)
  on conflict (endpoint) do update
  set user_id = excluded.user_id,
      p256dh = excluded.p256dh,
      auth = excluded.auth,
      created_at = now();
end;
$_$;

--
-- Name: saved_search_single_model(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.saved_search_single_model() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'UPDATE' or new.motorcycle_id is not null then
    new.motorcycle_ids := case
      when new.motorcycle_id is null then '{}'::uuid[]
      else array[new.motorcycle_id]
    end;
    new.motorcycle_id := null;
  end if;
  return new;
end;
$$;

--
-- Name: send_telegram(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_telegram(p_text text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  token text;
  chat  text;
begin
  select s.decrypted_secret into token
  from vault.decrypted_secrets s where s.name = 'telegram_bot_token';
  select s.decrypted_secret into chat
  from vault.decrypted_secrets s where s.name = 'telegram_chat_id';

  if token is null or chat is null then
    raise warning 'telegram_bot_token or telegram_chat_id is not in the Vault; message not sent';
    return null;
  end if;

  return net.http_post(
    url := 'https://api.telegram.org/bot' || token || '/sendMessage',
    body := jsonb_build_object('chat_id', chat, 'text', p_text),
    headers := jsonb_build_object('Content-Type', 'application/json'),
    timeout_milliseconds := 10000
  );
end;
$$;

--
-- Name: set_admin(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_admin(p_user uuid, p_admin boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform public.require_admin();
  if p_user = auth.uid() then
    raise exception 'You cannot change your own admin access' using errcode = '22023';
  end if;
  if not exists (select 1 from auth.users u
                 where u.id = p_user and not coalesce(u.is_anonymous, false)) then
    raise exception 'Unknown account %', p_user using errcode = 'P0002';
  end if;
  if p_admin then
    insert into public.app_admins (user_id) values (p_user) on conflict do nothing;
  else
    delete from public.app_admins where user_id = p_user;
  end if;
end;
$$;

