-- Name: set_initial_price(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_initial_price() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  new.initial_price := coalesce(new.initial_price, new.price);
  return new;
end;
$$;

--
-- Name: set_model_colours(uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_model_colours(p_motorcycle_id uuid, p_colours text[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform public.require_account();

  if not exists (select 1 from public.motorcycles m where m.id = p_motorcycle_id) then
    raise exception 'Unknown model %', p_motorcycle_id using errcode = 'P0002';
  end if;

  insert into public.user_models (user_id, motorcycle_id, tracked, min_year, colours)
  select auth.uid(), m.id, false, m.min_year, coalesce(p_colours, '{}')
  from public.motorcycles m where m.id = p_motorcycle_id
  on conflict (user_id, motorcycle_id)
  do update set colours = excluded.colours, updated_at = now();
end;
$$;

--
-- Name: set_model_min_year(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_model_min_year(p_motorcycle_id uuid, p_min_year integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform public.require_account();

  if p_min_year < 1990 or p_min_year > extract(year from now())::integer + 1 then
    raise exception 'Year % is out of range', p_min_year using errcode = '22023';
  end if;
  if not exists (select 1 from public.motorcycles m where m.id = p_motorcycle_id) then
    raise exception 'Unknown model %', p_motorcycle_id using errcode = 'P0002';
  end if;

  -- A year for a model not followed is kept for when it is.
  insert into public.user_models (user_id, motorcycle_id, tracked, min_year)
  values (auth.uid(), p_motorcycle_id, false, p_min_year)
  on conflict (user_id, motorcycle_id)
  do update set min_year = excluded.min_year, updated_at = now();

  perform public.refresh_collected_model(p_motorcycle_id);
end;
$$;

--
-- Name: set_model_new_price(uuid, numeric, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_model_new_price(p_motorcycle_id uuid, p_price numeric, p_checked_at date DEFAULT CURRENT_DATE) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform public.require_account();

  if p_price is not null and (p_price <= 0 or p_price > 200000) then
    raise exception 'Price % is out of range', p_price using errcode = '22023';
  end if;

  update public.motorcycles
  set new_price_reference  = p_price,
      new_price_checked_at = case when p_price is null then null
                                  else coalesce(p_checked_at, current_date) end,
      updated_at           = now()
  where id = p_motorcycle_id;

  if not found then
    raise exception 'Unknown model %', p_motorcycle_id using errcode = 'P0002';
  end if;
end;
$$;

--
-- Name: set_model_tracked(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_model_tracked(p_motorcycle_id uuid, p_tracked boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform public.require_account();

  if not exists (select 1 from public.motorcycles m where m.id = p_motorcycle_id) then
    raise exception 'Unknown model %', p_motorcycle_id using errcode = 'P0002';
  end if;

  insert into public.user_models (user_id, motorcycle_id, tracked, min_year)
  select auth.uid(), m.id, p_tracked, m.min_year
  from public.motorcycles m where m.id = p_motorcycle_id
  on conflict (user_id, motorcycle_id)
  do update set tracked = excluded.tracked, updated_at = now();

  perform public.refresh_collected_model(p_motorcycle_id);
end;
$$;

--
-- Name: set_photo_mark(uuid, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_photo_mark(p_listing uuid, p_photo integer, p_problem boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform public.require_admin();
  if p_photo is null or p_photo not between 0 and 2 then
    raise exception 'Only the first 3 photos can be marked' using errcode = '22023';
  end if;
  if p_problem is null then
    delete from public.photo_marks
    where user_id = auth.uid() and listing_id = p_listing and photo = p_photo;
  else
    insert into public.photo_marks (user_id, listing_id, photo, problem)
    values (auth.uid(), p_listing, p_photo, p_problem)
    on conflict (user_id, listing_id, photo)
      do update set problem = excluded.problem, marked_at = now();
  end if;
end;
$$;

--
-- Name: set_search_keys(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_search_keys(p_source text, p_keys jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  n integer;
begin
  update public.listings l
  set search_key = k.value
  from jsonb_each_text(p_keys) k
  where l.source = p_source
    and l.source_listing_id = k.key
    and l.search_key is distinct from k.value;

  get diagnostics n = row_count;
  return n;
end;
$$;

--
-- Name: single_owner_in_text(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.single_owner_in_text(p_variant text, p_description text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select regexp_replace(
           lower(concat_ws(' ', p_variant, p_description)),
           '(\mn[ãa]o\M|\mnunca\M|\mnot\M)\s+([^\s.,!?;]+\s+){0,3}?'
           '(primeir[oa]|[úu]nic[oa]|1\s*[ºªoa]|dono|first|one|single|only)\S*',
           ' ', 'g'
         ) ~ ('(primeiro|[úu]nico|1\s*[ºo])\s+(e\s+[úu]nico\s+)?(dono|propriet[áa]rio)'
              '|\m(dono|propriet[áa]rio)\s+[úu]nico'
              '|\m(apenas|s[óo]|somente)\s+(um|1)\s+(dono|propriet[áa]rio)'
              '|\m(um|1)\s+s[óo]\s+(dono|propriet[áa]rio)'
              '|\m1\s+(dono|propriet[áa]rio)\M'
              '|(primeira|1\s*[ªa])\s+m[ãa]o'
              '|\m(first|one|single|only)\s+owner')
$$;

--
-- Name: stamp_favourite_target(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stamp_favourite_target() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'INSERT' or new.target_price is distinct from old.target_price then
    new.target_set_at := case when new.target_price is null then null else now() end;
  end if;
  return new;
end;
$$;

--
-- Name: start_workflow(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_workflow(p_workflow text, p_kind text DEFAULT NULL::text) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_token    text;
  v_response extensions.http_response;
  v_at       timestamptz;
begin
  if p_workflow in ('push-test.yml', 'weekly-summary.yml') then
    perform public.require_account();
  else
    perform public.require_admin();
  end if;
  if p_workflow is null
     or p_workflow not in ('collect.yml', 'weekly-summary.yml', 'push-test.yml') then
    raise exception 'unknown workflow %', p_workflow using errcode = '22023';
  end if;
  if p_kind is not null and (p_workflow <> 'push-test.yml' or p_kind not in (
       'test', 'new_listing', 'price_reduction', 'excellent_opportunity',
       'listing_removed', 'back_on_market', 'target_price_reached',
       'run_failed', 'run_blocked', 'run_recovered')) then
    raise exception 'unknown kind %', p_kind using errcode = '22023';
  end if;

  -- One at a time per workflow, so two taps can't both pass the check.
  perform pg_advisory_xact_lock(hashtext('start_workflow ' || p_workflow));
  if exists (select 1 from public.workflow_starts w
             where w.workflow = p_workflow
               and (p_workflow = 'collect.yml' or w.started_by = auth.uid())
               and w.started_at > now() - case p_workflow
                 when 'collect.yml' then interval '15 minutes'
                 when 'push-test.yml' then interval '30 seconds'
                 else interval '2 minutes' end) then
    raise exception '% was started too recently', p_workflow
      using errcode = '55006';
  end if;

  select s.decrypted_secret into v_token
  from vault.decrypted_secrets s where s.name = 'github_dispatch_token';
  if v_token is null then
    raise exception 'github_dispatch_token is not in the Vault' using errcode = '55000';
  end if;

  perform extensions.http_set_curlopt('CURLOPT_TIMEOUT_MS', '15000');
  v_response := extensions.http((
    'POST',
    'https://api.github.com/repos/rafaelfaria1323/motorcycle-deal-tracker'
      || '/actions/workflows/' || p_workflow || '/dispatches',
    array[extensions.http_header('Authorization', 'Bearer ' || v_token),
          extensions.http_header('Accept', 'application/vnd.github+json'),
          extensions.http_header('X-GitHub-Api-Version', '2022-11-28'),
          extensions.http_header('User-Agent', 'motorcycle-deal-tracker')],
    'application/json',
    case p_workflow
      when 'weekly-summary.yml' then
        jsonb_build_object('ref', 'main',
                           'inputs', jsonb_build_object('account', auth.uid()))::text
      when 'push-test.yml' then
        jsonb_build_object('ref', 'main',
                           'inputs', jsonb_build_object(
                             'account', auth.uid(),
                             'kind', coalesce(p_kind, 'test')))::text
      else '{"ref": "main"}'
    end
  )::extensions.http_request);

  -- 204 = started (200 when GitHub answers with the run's details).
  if v_response.status not in (200, 204) then
    raise exception 'GitHub answered % to %', v_response.status, p_workflow
      using errcode = '58000';
  end if;

  insert into public.workflow_starts (workflow, started_by)
  values (p_workflow, auth.uid())
  returning started_at into v_at;
  return v_at;
end;
$$;

--
-- Name: store_photo_classifier(text, double precision[], double precision, integer, integer, double precision, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.store_photo_classifier(p_model text, p_weights double precision[], p_bias double precision, p_samples integer, p_problems integer, p_accuracy double precision, p_marks_key text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_ids uuid[];
begin
  insert into public.photo_classifiers
    (model, weights, bias, samples, problems, accuracy, marks_key)
  values (p_model, p_weights, p_bias, p_samples, p_problems, p_accuracy, p_marks_key)
  on conflict (model) do update
    set weights = excluded.weights, bias = excluded.bias,
        samples = excluded.samples, problems = excluded.problems,
        accuracy = excluded.accuracy, marks_key = excluded.marks_key,
        trained_at = now();

  v_ids := array(select distinct listing_id from public.listing_photo_features
                 where model = p_model);
  perform public.refresh_photo_hints(v_ids);
  return cardinality(v_ids);
end;
$$;

--
-- Name: store_photo_features(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.store_photo_features(p_model text, p_listings jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_ids uuid[] := array(select (e ->> 'id')::uuid from jsonb_array_elements(p_listings) e);
  n integer;
begin
  delete from public.listing_photo_features
  where listing_id = any (v_ids);

  insert into public.listing_photo_features (listing_id, photo, model, scores, features)
  select (e ->> 'id')::uuid, (p ->> 'photo')::smallint, p_model,
         coalesce(p -> 'scores', '{}'), decode(p ->> 'features', 'base64')
  from jsonb_array_elements(p_listings) e
  cross join lateral jsonb_array_elements(coalesce(e -> 'photos', '[]')) p
  on conflict (listing_id, photo) do nothing;

  update public.listings
  set photos_examined_at = now()
  where id = any (v_ids);
  get diagnostics n = row_count;

  perform public.refresh_photo_hints(v_ids);
  return n;
end;
$$;

--
-- Name: store_photo_hashes(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.store_photo_hashes(p_listings jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_ids uuid[];
  n integer;
begin
  select coalesce(array_agg((e ->> 'id')::uuid), '{}')
  into v_ids
  from jsonb_array_elements(p_listings) e;

  delete from public.listing_photo_hashes where listing_id = any(v_ids);
  delete from public.listing_photo_matches
  where listing_id = any(v_ids) or other_id = any(v_ids);

  insert into public.listing_photo_hashes (listing_id, position, hash)
  select (e ->> 'id')::uuid, h.ord::smallint, h.value::bigint
  from jsonb_array_elements(p_listings) e
  cross join lateral jsonb_array_elements_text(e -> 'hashes') with ordinality h(value, ord)
  on conflict (listing_id, position) do nothing;

  update public.listings
  set photos_hashed_at = now()
  where id = any(v_ids);
  get diagnostics n = row_count;

  with mine as (
    select listing_id, position, hash, bands
    from public.listing_photo_hashes
    where listing_id = any(v_ids)
  ),
  near as (
    select m.listing_id, m.position, o.listing_id as other_id
    from mine m
    join public.listing_photo_hashes o
      on o.bands && m.bands
     and o.listing_id <> m.listing_id
    where bit_count((m.hash # o.hash)::bit(64)) <= 5
  ),
  common as (
    select listing_id, position
    from near
    group by listing_id, position
    having count(distinct other_id) >= 5
  ),
  photos as (
    select listing_id, count(*) as total
    from public.listing_photo_hashes
    where listing_id in (select listing_id from near)
       or listing_id in (select other_id from near)
    group by listing_id
  ),
  pairs as (
    select n.listing_id, n.other_id, count(distinct n.position)::smallint as shared
    from near n
    where not exists (
      select 1 from common c
      where c.listing_id = n.listing_id and c.position = n.position
    )
    group by n.listing_id, n.other_id
  ),
  kept as (
    select p.*
    from pairs p
    join photos a on a.listing_id = p.listing_id
    join photos b on b.listing_id = p.other_id
    where p.shared >= 2 or a.total = 1 or b.total = 1
  )
  -- Both ways round; a pair stored in this call is found from both sides.
  insert into public.listing_photo_matches (listing_id, other_id, shared)
  select a, b, max(shared)
  from (
    select listing_id as a, other_id as b, shared from kept
    union all
    select other_id, listing_id, shared from kept
  ) both_ways
  group by a, b;

  return n;
end;
$$;

--
-- Name: store_push_keys(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.store_push_keys(p_public_key text, p_private_key text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  insert into public.push_config (public_key) values (p_public_key)
  on conflict (id) do nothing;
  if not found then
    return false;
  end if;
  perform vault.create_secret(p_private_key, 'vapid_private_key',
                              'Web Push private key (collector)');
  return true;
end;
$$;

--
-- Name: store_service_access(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.store_service_access(p_url text, p_key text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_name   text;
  v_value  text;
  v_id     uuid;
  v_stored text;
begin
  if p_url not like 'http%://%' or nullif(btrim(p_key), '') is null then
    raise exception 'Invalid service access' using errcode = '22023';
  end if;
  foreach v_name in array array['service_url', 'service_role_key'] loop
    v_value := case v_name when 'service_url' then rtrim(btrim(p_url), '/')
                           else btrim(p_key) end;
    select s.id, s.decrypted_secret into v_id, v_stored
    from vault.decrypted_secrets s where s.name = v_name;
    if v_id is null then
      perform vault.create_secret(v_value, v_name, 'Supabase Auth admin API (collector)');
    elsif v_stored is distinct from v_value then
      perform vault.update_secret(v_id, v_value);
    end if;
  end loop;
end;
$$;

--
-- Name: strip_phone_numbers(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.strip_phone_numbers() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  new.description := public.without_phone_numbers(new.description);
  new.variant := public.without_phone_numbers(new.variant);
  new.seller_name := public.without_phone_numbers(new.seller_name);
  return new;
end;
$$;

--
-- Name: text_contradictions(text, integer, integer, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.text_contradictions(p_description text, p_year integer, p_mileage integer, p_origin text, p_service_book boolean) RETURNS text[]
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  with t as (
    -- "IUC pago até ao ano de 2027" is no registration year.
    select regexp_replace(lower(coalesce(p_description, '')),
                          'at[ée]\s+(ao\s+|a\s+)?(ano|final)', ' ', 'g') as d
  ),
  found as (
    select
      (regexp_match(d,
        '(?:\mano|matr[ií]cula|matriculad[ao]|registo)\s*(?:de|em|:)?\s*((?:19|20)\d{2})\M'
      ))[1]::integer as text_year,
      regexp_match(d,
        '(?:\mtem|\mcom|apenas|\ms[oó]|\mkms?:?)\s+(\d{1,3}(?:[.\s]\d{3})+|\d+)\s*(mil)?\s*(?:km|kms|quil[oó]metros)\M'
      ) as km,
      regexp_replace(d,
        '(n[ãa]o|nunca)\s+(foi\s+|[ée]\s+)?importad[ao]', '', 'g'
      ) as d_no_negation,
      d
    from t
  ),
  values_found as (
    select
      text_year,
      case when km is not null then
        regexp_replace(km[1], '[.\s]', '', 'g')::numeric
        * case when km[2] is not null then 1000 else 1 end
      end as text_km,
      d_no_negation,
      d
    from found
  )
  select coalesce(array_agg(code order by code), '{}'::text[])
  from values_found,
  lateral (
    select 'text_year_mismatch' as code
    where text_year is not null and p_year is not null
      and abs(text_year - p_year) >= 2
      -- A year still to come is a date (inspection, insurance), not the bike's.
      and text_year <= extract(year from current_date)::integer
    union all
    select 'text_mileage_mismatch'
    where text_km is not null and p_mileage is not null
      and text_km > p_mileage * 1.2 and text_km - p_mileage >= 2000
    union all
    select 'text_origin_mismatch'
    where p_origin = 'national'
      and d_no_negation ~ '(importad[ao]|matr[ií]cula\s+(estrangeira|espanhola|francesa|alem[ãa]|italiana))'
    union all
    select 'text_service_book_mismatch'
    where p_service_book and d ~ '\msem\s+livro'
  ) codes
$$;

--
-- Name: track_price_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.track_price_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.price is not null and new.price is distinct from old.price then
    insert into public.listing_price_history (listing_id, price, observed_at)
    values (new.id, new.price, now());

    if new.status = 'active' then
      new.status := 'price_changed';
    end if;
  end if;
  return new;
end;
$$;

