--

CREATE FUNCTION public.tracked_by_me(m public.motorcycles) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select public.caller_tracks(m.id, null)
$$;

--
-- Name: user_tracks(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_tracks(p_user uuid, p_motorcycle_id uuid, p_year integer) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select exists (select 1 from public.user_models u
                 where u.user_id = p_user
                   and u.motorcycle_id = p_motorcycle_id
                   and u.tracked
                   and (p_year is null or p_year >= u.min_year))
$$;

--
-- Name: valued_extras(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.valued_extras(p_extras text[]) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select coalesce(array_agg(e order by e), '{}'::text[])
  from unnest(p_extras) e
  where e = any (array['quickshifter', 'exhaust', 'luggage', 'heated_grips',
                       'suspension', 'cruise_control', 'steering_damper',
                       'new_tyres'])
$$;

--
-- Name: weekly_summary_due(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.weekly_summary_due(p_now timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select extract(isodow from p_now at time zone 'Europe/Lisbon') = 1
     and extract(hour from p_now at time zone 'Europe/Lisbon') = 8
$$;

--
-- Name: without_phone_numbers(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.without_phone_numbers(p_text text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  phone constant text :=
    '(?<![0-9])(?:(?:\+|00)?351[ .-]?)?(?:'
    || '[29][0-9]{2}[ .-]?[0-9]{3}[ .-]?[0-9]{3}'
    || '|[29][0-9]{2}[ .-][0-9]{2}[ .-][0-9]{2}[ .-][0-9]{2}'
    || '|[29][0-9][ .-][0-9]{3}[ .-][0-9]{4}'
    || ')(?![0-9])';
  t text;
begin
  if p_text is null or p_text !~ phone then
    return p_text;
  end if;
  t := regexp_replace(p_text, phone, '', 'g');
  t := regexp_replace(t, '[ \t]{2,}', ' ', 'g');
  t := regexp_replace(t, '[ \t]+(\n|$)', '\1', 'g');
  t := regexp_replace(t, '(^|\n)[ \t]+', '\1', 'g');
  t := btrim(t);
  return nullif(t, '');
end;
$_$;

--
-- Name: year_score(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.year_score(p_year integer, p_reference_year integer DEFAULT (date_part('year'::text, CURRENT_DATE))::integer, p_points_per_year integer DEFAULT 10) RETURNS smallint
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select case
    when p_year is null then null
    else greatest(0, least(100,
      100 - (p_reference_year - p_year) * p_points_per_year
    ))::smallint
  end
$$;

--
