    CONSTRAINT listing_card_preferences_known_fields CHECK (((visible_fields <@ ARRAY['source'::text, 'deal_score'::text, 'price_change'::text, 'market_position'::text, 'year'::text, 'mileage'::text, 'location'::text, 'preferred_colour'::text, 'risk_score'::text, 'seller_type'::text, 'first_seen_at'::text, 'colour'::text, 'registrations'::text, 'service_book'::text, 'origin'::text, 'warranty_until'::text, 'dealer_warranty_months'::text, 'seller_name'::text, 'published_at'::text, 'site_refreshed_at'::text, 'status'::text]) AND (COALESCE(array_ndims(visible_fields), 1) = 1)))
